 /** Does an action pattern such as "doc:*" match an action such as "doc:read"? See README.md. */
 export function matchAction(pattern: string, action: string): boolean {
-  throw new Error("not implemented");
+  if (pattern === "*") return true;
+  if (pattern.endsWith(":*")) {
+    const prefix = pattern.slice(0, -1);
+    return action.startsWith(prefix) && action.length > prefix.length;
+  }
+  return pattern === action;
 }

 /** Does a resource pattern with * and ** segments match a path? See README.md. */
 export function matchResource(pattern: string, resource: string): boolean {
-  throw new Error("not implemented");
+  const pat = pattern.split("/").filter((s) => s.length > 0);
+  const res = resource.split("/").filter((s) => s.length > 0);
+  return matchSegments(pat, res, 0, 0);
 }
+
+function matchSegments(pat: string[], res: string[], pi: number, ri: number): boolean {
+  if (pi === pat.length) return ri === res.length;
+  const seg = pat[pi];
+  if (seg === "**") {
+    for (let i = ri; i <= res.length; i++) {
+      if (matchSegments(pat, res, pi + 1, i)) return true;
+    }
+    return false;
+  }
+  if (ri === res.length) return false;
+  if (seg === "*" || seg === res[ri]) return matchSegments(pat, res, pi + 1, ri + 1);
+  return false;
+}
